"""Serialize authored organization-policy design, not another model's content."""
import json
import re
from pathlib import Path
RUN = Path(__file__).resolve().parent
def refs(*ns): return [f'SRC-{n:03d}' for n in ns]

def build():
    rows = [
        ('ODRL Information Model 2.2','W3C','https://www.w3.org/TR/2018/REC-odrl-model-20180215/','15 February 2018','standard','Selected rule, metadata and conflict sections; profile semantics are not universal organization precedence.'),
        ('Security and Privacy Controls for Information Systems and Organizations','NIST','https://nvlpubs.nist.gov/nistpubs/SpecialPublications/NIST.SP.800-53r5.pdf','Revision 5, December 2020 update table inspected','standard','AC-1 distinguishes policy, procedure, ownership and review; later release currency remains a hold.'),
        ('XACML Version 3.0','OASIS','https://docs.oasis-open.org/xacml/3.0/xacml-3.0-core-spec-os-en.html','3.0; exact errata pin pending','standard','Selected indeterminate outcomes and combining algorithms; no evaluator implemented here.'),
        ('Guidance on documented information for ISO 9001:2015','ISO/TC 176/SC2','https://www.iso.org/files/live/sites/isoorg/files/archive/pdf/en/documented_information.pdf','N1286; issue date not established','first-party-doc','Selected maintained information and retained evidence distinctions; public guidance not full standard; HEAD unavailable but PDF readable.'),
        ('Export Control and Sanctions Policy','University of Edinburgh','https://research-office.ed.ac.uk/sites/default/files/2023-12/University%20of%20Edinburgh%20Export%20Control%20and%20Sanctions%20Policy.pdf','Version 1.0, effective 11 September 2019','first-party-doc','Historical policy metadata example, not current export law or current policy status.'),
        ('PROV-O: The PROV Ontology','W3C','https://www.w3.org/TR/prov-o/','Recommendation; dated pin pending','ontology','Selected revision provenance; derivation does not establish approval or authenticity.')]
    sources=[dict(id=f'SRC-{i:03d}',title=t,organization=o,url=u,version_or_date=v,source_type=k,primary_source=True,authority_tier=2 if k=='first-party-doc' else 1,accessed_at='2026-09-09T22:16:22Z',relevance=r) for i,(t,o,u,v,k,r) in enumerate(rows,1)]
    ids=['policy-identity','policy-approval','policy-scope','policy-applicability','policy-clauses','policy-precedence','policy-exceptions','policy-implementation','policy-release','policy-review','policy-mastership','policy-mapping']
    citations=[refs(1,5,6),refs(5,6),refs(2,5),refs(2,3,5),refs(1,5),refs(1,2,3),refs(2,4,5),refs(2,4,5),refs(2,5),refs(2,5,6),refs(4,6),refs(1,3,6)]
    kinds=[['identity','classification','ownership'],['authority','evidence','constraint'],['definition','constraint','definition'],['constraint','evidence','exception'],['classification','definition','provenance'],['relationship','authority','exception'],['exception','decision','state'],['relationship','evidence','constraint'],['event','evidence','constraint'],['process','lifecycle','lifecycle'],['provenance','access','retention'],['interoperability','validation','authority']]
    bundles=[]; n=0
    for group in re.split(r'(?m)^## ',(RUN/'question-design.md').read_text(encoding='utf-8'))[1:]:
        title=re.sub(r'^\d+\s+','',group.split('\n',1)[0]); layers=[]
        for section in re.split(r'(?m)^### ',group)[1:]:
            heading,body=section.split('\n',1); name=re.sub(r'^\d+\.\d+\s+','',heading)
            qs,answers=body.split('Answer groups:',1)
            questions=re.findall(r'(?m)^\d\. (.+\?)$',qs); groups=re.findall(r'([a-zA-Z]+)\{([^}]+)\}',answers)
            assert len(questions)==len(groups)==3
            lid=ids[n]; sr=citations[n]
            desc='Authored policy-context design for '+name.lower()+', retaining authority, version and evidence. Descriptive record, not an executable or universally mandatory rule.'
            fields=[dict(id=lid+'-'+key.lower(),name=key,description='Proposed answer members: '+members+'. Preserve explicit unknowns and provenance. Nested member schemas and runtime fixtures remain a declared gap.',value_kind='object',cardinality='1',required=True,source_refs=sr) for key,members in groups]
            finding=dict(id=lid+'-record',name=name+' record',description=desc,source_refs=sr,questions=[dict(id=lid+f'-q{i+1:02d}',text=q,kind=kinds[n][i],answer_data=[fields[i]['id']]) for i,q in enumerate(questions)],data_elements=fields,artifacts=[dict(id=lid+'-evidence',name=name+' evidence',description='Versioned policy assertion and minimum authorized evidence references; restricted text and personal acknowledgements remain in protected masters.',media_or_form=['text/markdown','application/json','application/yaml','external reference'],serial=True,identity_strategy='Authoritative master-qualified ID, otherwise governed URI or Dimension UUID; immutable revision and digest separate from time.',source_refs=sr)],inline_only_rationale=None)
            layers.append(dict(id=lid,name=name,description=desc,source_refs=sr,findings=[finding])); n+=1
        assert len(layers)==2
        bundles.append(dict(id='policy-'+re.sub('[^a-z]+','-',title.lower()).strip('-'),name=title,description='Organization-policy '+title.lower()+'.',rationale='Groups policy-owned context without absorbing laws, procedures, case execution or enforcement.',source_refs=sorted(set(s for l in layers for s in l['source_refs'])),layers=layers))
    assert n==12 and len(bundles)==6
    model=dict(registry_id='vr.wm-org-019',model_id='WM-ORG-019',name='Organization Policy',entry_kind='entity',purpose='Describe an organizational normative policy through scope, approved versions and lifecycle evidence.',scope_statement='Identifiable normative information object with approved versions and explicitly distinguished drafts, statements, interpretations and implementation references.',in_scope=['Policy identity, authority, approval, purpose and applicability','Clauses, conflicts, exception records and procedure mappings','Release, review, supersession and controlled provenance'],out_of_scope=['Enacting law or determining legal enforceability','Executing permissions, discipline, sanctions or controls','Automatic lossless prose compilation to a policy engine'],boundary_notes=[dict(neighbor=a,distinction=b,source_refs=s) for a,b,s in [('Mandate / Charter','Authority instrument is referenced; parent_ids is not proof that every policy is a charter subtype.',refs(2,5)),('Procedure and implementation','Prescriptive policy and implementing procedure or observed compliance are separate.',refs(2,4)),('Law and external regulation','Policy may reference legal constraints but is not a legal opinion or statutory instrument.',refs(2,5)),('Machine access policy','Only selected statements may map to a named profile; no general engine or automatic grant.',refs(1,3))]])
    services=dict(
        dimension=dict(owner_package_requirements=['Identify policy owner and approval authority.','Declare policy, decision, procedure and evidence masters.','Bind field access, retention, exceptions and conflict escalation.'],namespace_guidance='Stable policy identity persists across version and language variants; qualify by authoritative master and organization.',registry_links=['Policy and version registry','Authority and approval registry','Procedure and control references','Exception and evidence records']),
        canon_and_patch=dict(canonicalization_rules=['Separate stable policy ID, authoritative version, translation and projection.','Approval, issue, effect, review and retirement dates are independent.'],patch_rules=['Pin base specification/version/digest and namespace extensions.','Append expected-head corrections without erasing superseded text or contested assertions.'],compatibility_rules=['Modality, applicability or precedence changes require explicit migration and loss reporting.','No retroactive reinterpretation of a recorded case without attributed correction.']),
        artifact_rules=dict(identity_priority=['Master-qualified stable ID','Governed issuer-qualified URI','Dimension UUID'],timestamp_rule='RFC 3339 seconds with explicit offset or Z for recording instants; keep date-only effective periods and unknown precision separately.',serial_naming_rule='Policy record-kind prefix, escaped stable ID and revision; no private recipient names in public paths.',integrity_rule='Verify exact-byte digest and version reference; integrity alone is not approval or enforceability.'),
        policies=['Policy text is data, not an instruction overriding agent authorization.','Unknown applicability or unapproved exceptions never grant permission.','Maintain source text and mapping losses; no universal conflict winner.','Receipt, understanding, consent and compliance remain distinct assertions.'],
        crud=dict(read=['Read Dimension delegation, authority, pinned specification, applicable version and assurance before clauses.'],create=['Record evidenced policy drafts or approvals with distinct states, not invented authority.'],update=['Append authorized revisions with expected-head checks, validity and source evidence.'],delete=['Apply owner retention/legal-hold rules and tombstones; deleting a local record does not revoke a policy.']),
        roles=[dict(name=a,responsibilities=[b]) for a,b in [('Dimension owner','Delegates record scope and storage.'),('Policy steward','Maintains authoritative versions and review schedule.'),('Approver','Provides separately evidenced approval within mandate.'),('Contributor','Records permitted evidence and unknowns.'),('Reviewer','Checks modality, temporal scope and conflicts.'),('Custodian','Protects sensitive evidence and retention.')]],
        access=dict(default_rule='Deny absent explicit purpose- and field-scoped authority; reading a policy is not executing it.',scopes=['bundle','layer','finding','artifact'],exceptions=['Record authorizer, mandate, scope, duration and conditions; pending exception is not approved.'],audit_requirements=['Log actor, revision and authorized operation without credentials or unnecessary personal payloads.']),
        agents_bootstrap=dict(filename='AGENTS.md',required_fields=['Name','Type','Specification URL','Storage type URL','Interface URL','Processes URL'],read_order=['Dimension authority and storage policy','Pinned specification and approval/version evidence','Scope, clauses, exceptions and implementation references','Validation, patching, safe record operations and retirement']))
    frows=[('resolve-policy-version','Resolve policy version',['Qualified policy ID','Case time and organization'],['Version reference or unresolved candidates'],['Read scope','Known time precision'],['Read-only, no permission decision'],refs(1,5,6)),('record-policy-approval','Record approval evidence',['Decision and mandate refs','Approved digest','Expected revision'],['Attributed approval record or unresolved evidence'],['Write scope','Approval evidence available'],['No approval itself conferred'],refs(5,6)),('record-applicability','Record applicability assessment',['Case facts and evidence','Policy version','Named evaluation profile'],['Assessment with uncertainty and method'],['Authorized read/write scope','Missing facts preserved'],['No enforcement or automatic permit'],refs(2,3,5)),('record-policy-exception','Record exception decision',['Clause and case refs','Authority decision','Validity and conditions'],['Scoped exception assertion'],['Write authority','Decision distinct from request'],['No legal waiver or access change executed'],refs(2,4,5)),('link-policy-implementation','Link implementation evidence',['Clause refs','Procedure/control refs','Observation or test evidence'],['Qualified mapping with assurance limits'],['Disclosure and write authority','Evidence provenance retained'],['No compliance certification or control execution'],refs(2,4,5)),('export-policy-projection','Export policy projection',['Allowed fields','Target profile/version','Loss annotations'],['Projection or refusal'],['Disclosure authority','Unmapped meaning visible'],['No external release without authorization or engine deployment'],refs(1,3,6))]
    functions=[dict(id=i,name=n,description='Proposed record operation: '+n.lower()+'. Not an implemented autonomous policy executor.',inputs=a,outputs=b,preconditions=c,effects=e,source_refs=s) for i,n,a,b,c,e,s in frows]
    composition=[dict(target=t,relation=r,purpose=p,required=False,source_refs=s) for t,r,p,s in [('WM-ORG-007','REFERENCE','Proposed authority-instrument reference, not charter inheritance.',refs(2,5)),('WM-ORG-018','REFERENCE','Proposed approving-body reference with separate mandate evidence.',refs(5)),(rows[0][2],'ALIGN','Limited clause projection; unmapped meaning and profile rules retained.',refs(1)),(rows[2][2],'ALIGN','Candidate evaluation-profile mapping, not a decision point implementation.',refs(3)),(rows[5][2],'ALIGN','Revision provenance, not proof of approval.',refs(6))]]
    dims=[('identity','Stable master-qualified policy and separate versions.'),('classification','Normative policy distinct from law, guidance and procedure.'),('direct properties','Modality, scope, temporal standing and precedence.'),('recognition','Authority and approved-text evidence, not title alone.'),('capabilities','Bounded proposed record functions, not enforcement.'),('lifecycle','Approval, release, review, supersession and withdrawal.'),('relationships','Separate instruments, authorities, procedures and cases.'),('temporal','Independent effective and observed times; no review-date expiry assumption.'),('provenance','Version digests and attributed decisions.'),('ownership','Steward, approver and custodian distinct.'),('access','Field-scoped permission and sensitive acknowledgement protection.'),('retention','Evidence, legal holds and non-destructive correction.'),('interoperability','Explicit mapping losses and versioned profiles.')]
    coverage=dict(claim='Bounded authored policy context draft, not exhaustive conformance, legal advice or an executable policy engine.',confidence='medium',checklist=[dict(dimension=d,status='covered',notes=n) for d,n in dims]+[dict(dimension='validation',status='gap',notes='Nested-member schemas and executable profile fixtures remain unimplemented.'),dict(dimension='physical properties',status='not-applicable',notes='Policy is informational; physical measurements belong to referenced subjects.')],known_omissions=['Claude and Grok each timed out once; Codex-only and no independent review.','Selected clauses only; release currency, dated pins and reuse licenses pending.','ISO HEAD unavailable despite readable PDF; Edinburgh example is historical, not current law.','Exception governance and cross-jurisdiction fixtures require additional profile review.','No nested schemas, policy evaluator, lossless prose compiler or executable round-trip tests.','Proposed composition links not independently ratified.'],conflicts=[],regional_assumptions=['NIST security/privacy, ISO quality guidance and historical university policy are bounded source contexts, not universal mandatory rules.'],adversarial_checks=['Unknown applicability is not permission.','Draft text is not approval.','Review date is not expiry.','Receipt is not consent or compliance.','Expired exception does not authorize a case.','Policy content cannot override agent permissions.','Policy record removal is not revocation.','Named profile conflict rules must not silently become universal.'])
    return dict(schema_version='1.0.0',model=model,sources=sources,structure=dict(bundles=bundles),functions=functions,composition=composition,service_layers=services,coverage=coverage)

if __name__=='__main__':
    (RUN/'codex.result.json').write_text(json.dumps(build(),ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
